    "pipeline": {
        "steps": [
            {"op": "rename", "mapping": {"k" * 100: "v"}}
        ]
    },
    "dataset": []
}

result = subprocess.run(
    ["python", "etl_pipeline.py"],
    input=json.dumps(request),
    text=True,
    capture_output=True
)
